182:        if (pref.getFragment() != null) {
183:            Fragment fragment = Fragment.instantiate(/* context= */ this, pref.getFragment(),
184:                    pref.getExtras());
185:            launchFragment(fragment);
186:            return true;
187:        }
188:        return false;
189:    }
190:
191:    /**
192:     * Gets the fragment to show onCreate. If null, the activity will not perform an initial
193:     * fragment transaction.
194:     */
195:    @Nullable
196:    protected abstract Fragment getInitialFragment();
197:
198:    protected void launchIfDifferent(Fragment newFragment) {
199:        Fragment currentFragment = getCurrentFragment();
200:        if ((newFragment != null) && differentFragment(newFragment, currentFragment)) {
201:            LOG.d("launchIfDifferent: " + newFragment + " replacing " + currentFragment);
202:            launchFragment(newFragment);
203:        }
204:    }
205:
206:    protected Fragment getCurrentFragment() {
207:        return getSupportFragmentManager().findFragmentById(R.id.fragment_container);
208:    }
209:
210:    /**
211:     * Returns {code true} if newFragment is different from current fragment.
212:     */
213:    private boolean differentFragment(Fragment newFragment, Fragment currentFragment) {
214:        return (currentFragment == null)
215:                || (!currentFragment.getClass().equals(newFragment.getClass()));
216:    }
217:
218:    private void hideKeyboard() {
219:        InputMethodManager imm = (InputMethodManager) this.getSystemService(
220:                Context.INPUT_METHOD_SERVICE);
221:        imm.hideSoftInputFromWindow(getWindow().getDecorView().getWindowToken(), 0);
222:    }
223:
224:    private void updateBlockingView(@Nullable Fragment currentFragment) {
225:        if (currentFragment instanceof BaseFragment) {
226:            boolean canBeShown = ((BaseFragment) currentFragment).canBeShown(mCarUxRestrictions);
227:            mRestrictedMessage.setVisibility(canBeShown ? View.GONE : View.VISIBLE);
228:        }
229:    }
230:}
