18:
19:import android.car.drivingstate.CarUxRestrictions;
20:import android.car.drivingstate.CarUxRestrictionsManager.OnUxRestrictionsChangedListener;
21:import android.content.Context;
22:
23:import androidx.annotation.IntDef;
24:import androidx.annotation.NonNull;
25:import androidx.lifecycle.DefaultLifecycleObserver;
26:import androidx.lifecycle.LifecycleOwner;
27:import androidx.preference.Preference;
28:
29:import com.android.car.settings.R;
30:
31:import java.lang.annotation.Retention;
32:import java.lang.annotation.RetentionPolicy;
33:import java.util.Arrays;
34:import java.util.HashSet;
35:import java.util.Set;
36:
37:/**
38: * Controller which encapsulates the business logic associated with a {@link Preference}. All car
39: * settings controllers should extend this class.
40: *
41: * <p>Controllers are responsible for populating and modifying the presentation of an associated
42: * preference while responding to changes in system state. This is enabled via {@link
43: * SettingsFragment} which registers controllers as observers on its lifecycle and dispatches
44: * {@link CarUxRestrictions} change events to the controllers via the {@link
45: * OnUxRestrictionsChangedListener} interface.
46: *
47: * <p>Controllers should be instantiated from XML. To do so, define a preference and include the
48: * {@code controller} attribute in the preference tag and assign the fully qualified class name.
49: *
50: * <p>For example:
51: * <pre>{@code
52: * <Preference
53: *     android:key="my_preference_key"
54: *     android:title="@string/my_preference_title"
55: *     android:icon="@drawable/ic_settings"
56: *     android:fragment="com.android.settings.foo.MyFragment"
57: *     settings:controller="com.android.settings.foo.MyPreferenceController"/>
58: * }</pre>
59: *
60: * <p>Subclasses must implement {@link #getPreferenceType()} to define the upper bound type on the
61: * {@link Preference} that the controller is associated with. For example, a bound of {@link
62: * androidx.preference.PreferenceGroup} indicates that the controller will utilize preference group
63: * methods in its operation. {@link #setPreference(Preference)} will throw an {@link
64: * IllegalArgumentException} if not passed a subclass of the upper bound type.
65: *
66: * <p>Subclasses may implement any or all of the following methods (see method Javadocs for more
67: * information):
68: *
69: * <ul>
70: * <li>{@link #checkInitialized()}
71: * <li>{@link #onCreateInternal()}
72: * <li>{@link #getAvailabilityStatus()}
73: * <li>{@link #onStartInternal()}
74: * <li>{@link #onResumeInternal()}
75: * <li>{@link #onPauseInternal()}
76: * <li>{@link #onStopInternal()}
77: * <li>{@link #onDestroyInternal()}
78: * <li>{@link #updateState(Preference)}
79: * <li>{@link #onApplyUxRestrictions(CarUxRestrictions)}
80: * <li>{@link #handlePreferenceChanged(Preference, Object)}
81: * <li>{@link #handlePreferenceClicked(Preference)}
82: * </ul>
83: *
84: * @param <V> the upper bound on the type of {@link Preference} on which the controller
85: *            expects to operate.
86: */
87:public abstract class PreferenceController<V extends Preference> implements
88:        DefaultLifecycleObserver,
89:        OnUxRestrictionsChangedListener {
90:
91:    /**
92:     * Denotes the availability of a setting.
93:     *
94:     * @see #getAvailabilityStatus()
95:     */
96:    @Retention(RetentionPolicy.SOURCE)
97:    @IntDef({AVAILABLE, CONDITIONALLY_UNAVAILABLE, UNSUPPORTED_ON_DEVICE, DISABLED_FOR_USER})
98:    public @interface AvailabilityStatus {
99:    }
100:
101:    /**
102:     * The setting is available.
103:     */
104:    public static final int AVAILABLE = 0;
105:
106:    /**
107:     * The setting is currently unavailable but may become available in the future. Use
108:     * {@link #DISABLED_FOR_USER} if it describes the condition more accurately.
109:     */
110:    public static final int CONDITIONALLY_UNAVAILABLE = 1;
111:
112:    /**
113:     * The setting is not and will not be supported by this device.
114:     */
115:    public static final int UNSUPPORTED_ON_DEVICE = 2;
116:
117:    /**
118:     * The setting cannot be changed by the current user.
119:     */
120:    public static final int DISABLED_FOR_USER = 3;
121:
122:    /**
123:     * Indicates whether all Preferences are configured to ignore UX Restrictions Event.
124:     */
125:    private final boolean mAlwaysIgnoreUxRestrictions;
126:
127:    /**
128:     * Set of the keys of Preferences that ignore UX Restrictions. When mAlwaysIgnoreUxRestrictions
129:     * is configured to be false, then only the Preferences whose keys are contained in this Set
130:     * ignore UX Restrictions.
131:     */
132:    private final Set<String> mPreferencesIgnoringUxRestrictions;
133:
134:    private final Context mContext;
135:    private final String mPreferenceKey;
136:    private final FragmentController mFragmentController;
137:
138:    private CarUxRestrictions mUxRestrictions;
139:    private V mPreference;
140:    private boolean mIsCreated;
141:
142:    /**
143:     * Controllers should be instantiated from XML. To pass additional arguments see
144:     * {@link SettingsFragment#use(Class, int)}.
145:     */
146:    public PreferenceController(Context context, String preferenceKey,
147:            FragmentController fragmentController, CarUxRestrictions uxRestrictions) {
148:        mContext = context;
149:        mPreferenceKey = preferenceKey;
150:        mFragmentController = fragmentController;
151:        mUxRestrictions = uxRestrictions;
152:        mPreferencesIgnoringUxRestrictions = new HashSet<String>(Arrays.asList(
153:                mContext.getResources().getStringArray(R.array.config_ignore_ux_restrictions)));
154:        mAlwaysIgnoreUxRestrictions =
155:                mContext.getResources().getBoolean(R.bool.config_always_ignore_ux_restrictions);
156:    }
157:
158:    /**
159:     * Returns the context used to construct the controller.
160:     */
161:    protected final Context getContext() {
162:        return mContext;
163:    }
164:
165:    /**
166:     * Returns the key for the preference managed by this controller set at construction.
167:     */
168:    protected final String getPreferenceKey() {
169:        return mPreferenceKey;
170:    }
171:
172:    /**
173:     * Returns the {@link FragmentController} used to launch fragments and go back to previous
174:     * fragments. This is set at construction.
175:     */
176:    protected final FragmentController getFragmentController() {
177:        return mFragmentController;
178:    }
179:
180:    /**
181:     * Returns the current {@link CarUxRestrictions} applied to the controller. Subclasses may use
182:     * this to limit which content is displayed in the associated preference. May be called anytime.
183:     */
184:    protected final CarUxRestrictions getUxRestrictions() {
185:        return mUxRestrictions;
186:    }
187:
188:    /**
189:     * Returns the preference associated with this controller. This may be used in any of the
190:     * lifecycle methods, as the preference is set before they are called..
191:     */
192:    protected final V getPreference() {
193:        return mPreference;
194:    }
195:
196:    /**
197:     * Called by {@link SettingsFragment} to associate the controller with its preference after the
198:     * screen is created. This is guaranteed to be called before {@link #onCreateInternal()}.
199:     *
200:     * @throws IllegalArgumentException if the given preference does not match the type
201:     *                                  returned by {@link #getPreferenceType()}
202:     * @throws IllegalStateException    if subclass defined initialization is not
203:     *                                  complete.
204:     */
205:    final void setPreference(Preference preference) {
206:        PreferenceUtil.requirePreferenceType(preference, getPreferenceType());
207:        mPreference = getPreferenceType().cast(preference);
208:        mPreference.setOnPreferenceChangeListener(
209:                (changedPref, newValue) -> handlePreferenceChanged(
210:                        getPreferenceType().cast(changedPref), newValue));
211:        mPreference.setOnPreferenceClickListener(
212:                clickedPref -> handlePreferenceClicked(getPreferenceType().cast(clickedPref)));
213:        checkInitialized();
214:    }
215:
216:    /**
217:     * Called by {@link SettingsFragment} to notify that the applied ux restrictions have changed.
218:     * The controller will refresh its UI accordingly unless it is not yet created. In that case,
219:     * the UI will refresh once created.
220:     */
221:    @Override
222:    public final void onUxRestrictionsChanged(CarUxRestrictions uxRestrictions) {
223:        mUxRestrictions = uxRestrictions;
224:        refreshUi();
225:    }
226:
227:    /**
228:     * Updates the preference presentation based on its {@link #getAvailabilityStatus()} status. If
229:     * the controller is available, the associated preference is shown and a call to {@link
230:     * #updateState(Preference)} and {@link #onApplyUxRestrictions(CarUxRestrictions)} are
231:     * dispatched to allow the controller to modify the presentation for the current state. If the
232:     * controller is not available, the associated preference is hidden from the screen. This is a
233:     * no-op if the controller is not yet created.
234:     */
235:    public final void refreshUi() {
236:        if (!mIsCreated) {
237:            return;
238:        }
239:        if (getAvailabilityStatus() == AVAILABLE) {
240:            mPreference.setVisible(true);
241:            mPreference.setEnabled(true);
242:            updateState(mPreference);
243:            onApplyUxRestrictions(mUxRestrictions);
244:        } else {
245:            mPreference.setVisible(false);
246:        }
247:    }
248:
249:    // Controller lifecycle ========================================================================
250:
251:    /**
252:     * Dispatches a call to {@link #onCreateInternal()} and {@link #refreshUi()} to enable
253:     * controllers to setup initial state before a preference is visible. If the controller is
254:     * {@link #UNSUPPORTED_ON_DEVICE}, the preference is hidden and no further action is taken.
255:     */
256:    @Override
257:    public final void onCreate(@NonNull LifecycleOwner owner) {
258:        if (getAvailabilityStatus() == UNSUPPORTED_ON_DEVICE) {
259:            mPreference.setVisible(false);
260:            return;
261:        }
262:        onCreateInternal();
263:        mIsCreated = true;
264:        refreshUi();
265:    }
266:
267:    /**
268:     * Dispatches a call to {@link #onStartInternal()} and {@link #refreshUi()} to account for any
269:     * state changes that may have occurred while the controller was stopped. Returns immediately
270:     * if the controller is {@link #UNSUPPORTED_ON_DEVICE}.
271:     */
272:    @Override
273:    public final void onStart(@NonNull LifecycleOwner owner) {
274:        if (getAvailabilityStatus() == UNSUPPORTED_ON_DEVICE) {
275:            return;
276:        }
277:        onStartInternal();
278:        refreshUi();
279:    }
