17:package com.android.car.settings.common;
18:
19:import static com.android.car.settings.common.PreferenceXmlParser.METADATA_CONTROLLER;
20:import static com.android.car.settings.common.PreferenceXmlParser.METADATA_KEY;
21:
22:import android.annotation.NonNull;
23:import android.annotation.XmlRes;
24:import android.car.drivingstate.CarUxRestrictions;
25:import android.content.Context;
26:import android.os.Bundle;
27:import android.text.TextUtils;
28:
29:import org.xmlpull.v1.XmlPullParserException;
30:
31:import java.io.IOException;
32:import java.lang.reflect.Constructor;
33:import java.lang.reflect.InvocationTargetException;
34:import java.util.ArrayList;
35:import java.util.List;
36:
37:/**
38: * Helper to load {@link PreferenceController} instances from XML. Based on com.android
39: * .settings.core.PreferenceControllerListHelper.
40: */
41:class PreferenceControllerListHelper {
42:    private PreferenceControllerListHelper() {
43:    }
44:
45:    /**
46:     * Creates a list of {@link PreferenceController}.
47:     *
48:     * @param context the {@link Context} used to instantiate the controllers.
49:     * @param xmlResId the XML resource containing the metadata of the controllers to
50:     *         create.
51:     * @param fragmentController a valid {@link FragmentController} the preference
52:     *         controllers can use to navigate.
53:     * @param uxRestrictions the current {@link CarUxRestrictions}.
54:     * @throws IllegalArgumentException if the XML resource cannot be parsed, if the XML
55:     *         resource contains elements which declare controllers without preference keys, if the
56:     *         XML resource contains controllers which cannot be instantiated successfully.
57:     */
58:    @NonNull
59:    static List<PreferenceController> getPreferenceControllersFromXml(Context context,
60:            @XmlRes int xmlResId, FragmentController fragmentController,
61:            CarUxRestrictions uxRestrictions) {
62:        List<PreferenceController> controllers = new ArrayList<>();
63:        List<Bundle> preferenceMetadata;
64:        try {
65:            preferenceMetadata = PreferenceXmlParser.extractMetadata(context, xmlResId,
66:                    PreferenceXmlParser.MetadataFlag.FLAG_NEED_KEY
67:                            | PreferenceXmlParser.MetadataFlag.FLAG_NEED_PREF_CONTROLLER);
68:        } catch (IOException | XmlPullParserException e) {
69:            throw new IllegalArgumentException(
70:                    "Failed to parse preference XML for getting controllers", e);
71:        }
72:
73:        for (Bundle metadata : preferenceMetadata) {
74:            String controllerName = metadata.getString(METADATA_CONTROLLER);
75:            if (TextUtils.isEmpty(controllerName)) {
76:                continue; // Preference does not require a controller.
77:            }
78:            String key = metadata.getString(METADATA_KEY);
79:            if (TextUtils.isEmpty(key)) {
80:                throw new IllegalArgumentException("Missing key for controller: " + controllerName);
81:            }
82:            controllers.add(createInstance(controllerName, context, key, fragmentController,
83:                    uxRestrictions));
84:        }
85:
86:        return controllers;
87:    }
88:
89:    private static PreferenceController createInstance(String controllerName,
90:            Context context, String key, FragmentController fragmentController,
91:            CarUxRestrictions restrictionInfo) {
92:        try {
93:            Class<?> clazz = Class.forName(controllerName);
94:            Constructor<?> preferenceConstructor = clazz.getConstructor(Context.class, String.class,
95:                    FragmentController.class, CarUxRestrictions.class);
96:            Object[] params = new Object[]{context, key, fragmentController, restrictionInfo};
97:            return (PreferenceController) preferenceConstructor.newInstance(params);
98:        } catch (ClassNotFoundException | NoSuchMethodException | InstantiationException
99:                | InvocationTargetException | IllegalAccessException e) {
100:            throw new IllegalArgumentException(
101:                    "Invalid preference controller: " + controllerName, e);
102:        }
103:    }
104:}
