37:
38:import javax.annotation.Nullable;
39:
40:/**
41: * Class to manage the callbacks needed to calculate network stats for an application.
42: */
43:public class AppsNetworkStatsManager {
44:
45:    /**
46:     * Callback that is called once the AppsNetworkStats is loaded.
47:     */
48:    public interface Callback {
49:        /**
50:         * Called when the data is successfully loaded from
51:         * {@link AppsNetworkStatsManager.AppsNetworkStatsResult}.
52:         */
53:        void onDataLoaded(@Nullable NetworkStats stats, @Nullable int[] restrictedUids);
54:    }
55:
56:    private static final Logger LOG = new Logger(AppsNetworkStatsManager.class);
57:    private static final int NETWORK_STATS_ID = 1;
58:
59:    private final Context mContext;
60:    private final NetworkPolicyManager mNetworkPolicyManager;
61:    private final List<AppsNetworkStatsManager.Callback> mAppsNetworkStatsListeners =
62:            new ArrayList<>();
63:
64:    private INetworkStatsSession mStatsSession;
65:
66:    AppsNetworkStatsManager(Context context) {
67:        mContext = context;
68:        mNetworkPolicyManager = NetworkPolicyManager.from(context);
69:        try {
70:            mStatsSession = INetworkStatsService.Stub.asInterface(
71:                    ServiceManager.getService(Context.NETWORK_STATS_SERVICE)).openSession();
72:        } catch (RemoteException e) {
73:            LOG.e("Could not open a network session", e);
74:        }
75:    }
76:
77:    /**
78:     * Registers a listener that will be notified once the data is loaded.
79:     */
80:    public void registerListener(AppsNetworkStatsManager.Callback appsNetworkStatsListener) {
81:        if (!mAppsNetworkStatsListeners.contains(appsNetworkStatsListener)) {
82:            mAppsNetworkStatsListeners.add(appsNetworkStatsListener);
83:        }
84:    }
85:
86:    /**
87:     * Unregisters the listener.
88:     */
89:    public void unregisterListener(AppsNetworkStatsManager.Callback appsNetworkStatsListener) {
90:        mAppsNetworkStatsListeners.remove(appsNetworkStatsListener);
91:    }
92:
93:    /**
94:     * Start calculating the storage stats.
95:     */
96:    public void startLoading(LoaderManager loaderManager, Bundle bundle) {
97:        loaderManager.restartLoader(NETWORK_STATS_ID, bundle, new AppsNetworkStatsResult());
98:    }
99:
100:    private void onAppsNetworkStatsLoaded(NetworkStats stats, int[] restrictedUids) {
101:        for (AppsNetworkStatsManager.Callback listener : mAppsNetworkStatsListeners) {
102:            listener.onDataLoaded(stats, restrictedUids);
103:        }
104:    }
105:
106:    /**
107:     * Callback to calculate applications network stats.
108:     */
109:    private class AppsNetworkStatsResult implements LoaderManager.LoaderCallbacks<NetworkStats> {
110:        @Override
111:        public Loader<NetworkStats> onCreateLoader(int id, Bundle args) {
112:            return new SummaryForAllUidLoader(mContext, mStatsSession, args);
113:        }
114:
115:        @Override
116:        public void onLoadFinished(Loader<NetworkStats> loader, NetworkStats data) {
117:            int[] restrictedUids = mNetworkPolicyManager.getUidsWithPolicy(
118:                    POLICY_REJECT_METERED_BACKGROUND);
119:            onAppsNetworkStatsLoaded(data, restrictedUids);
120:        }
121:
122:        @Override
123:        public void onLoaderReset(Loader<NetworkStats> loader) {
124:            onAppsNetworkStatsLoaded(/* stats= */ null, /* restrictedUids= */ new int[0]);
125:        }
126:    }
127:}

