30:/**
31: * An invisible retained worker fragment to track the AsyncWork that saves
32: * the chosen lock credential (pattern/pin/password).
33: */
34:public class SaveLockWorker extends Fragment {
35:    /**
36:     * Callback when lock save has finished
37:     */
38:    interface Listener {
39:        void onChosenLockSaveFinished(boolean isSaveSuccessful);
40:    }
41:
42:    private static final Logger LOG = new Logger(SaveLockWorker.class);
43:
44:    private Listener mListener;
45:    private boolean mFinished;
46:    private boolean mIsSaveSuccessful;
47:    private LockPatternUtils mUtils;
48:    private int mUserId;
49:
50:    private LockscreenCredential mEnteredCredential;
51:    private LockscreenCredential mCurrentCredential;
52:    private int mRequestedQuality;
53:
54:    final LockPatternUtils getUtils() {
55:        return mUtils;
56:    }
57:
58:    final int getUserId() {
59:        return mUserId;
60:    }
61:
62:    final boolean isFinished() {
63:        return mFinished;
64:    }
65:
66:    @Override
67:    public void onCreate(Bundle savedInstanceState) {
68:        super.onCreate(savedInstanceState);
69:        setRetainInstance(true);
70:    }
71:
72:    @Override
73:    public void onDestroy() {
74:        super.onDestroy();
75:
76:        PasswordHelper.zeroizeCredentials(mEnteredCredential, mCurrentCredential);
77:    }
78:
79:    final void init(int userId) {
80:        mUtils = new LockPatternUtils(getContext());
81:        mUserId = userId;
82:    }
83:
84:    void start(int userId, LockscreenCredential enteredCredential,
85:            LockscreenCredential currentCredential) {
86:        init(userId);
87:        mEnteredCredential = enteredCredential;
88:        mCurrentCredential = currentCredential != null ? currentCredential
89:                : LockscreenCredential.createNone();
90:        start();
91:    }
92:    /**
93:     * Start executing the async task.
94:     */
95:    private void start() {
96:        mFinished = false;
97:        new Task().executeOnExecutor(AsyncTask.THREAD_POOL_EXECUTOR);
98:    }
99:
100:    /**
101:     * Set the listener to get callback when finished saving the chosen lock.
102:     */
103:    public void setListener(Listener listener) {
104:        if (mListener != listener) {
105:            mListener = listener;
106:            if (mFinished && mListener != null) {
107:                mListener.onChosenLockSaveFinished(mIsSaveSuccessful);
108:            }
109:        }
110:    }
111:
112:    @VisibleForTesting
113:    boolean saveAndVerifyInBackground(Void... params) {
114:        boolean isSaveSuccessful = true;
115:
116:        try {
117:            saveLock();
118:        } catch (Exception e) {
119:            LOG.e("Save lock exception", e);
120:            isSaveSuccessful = false;
121:        }
122:
123:        return isSaveSuccessful;
124:    }
125:
126:    private void finish(boolean isSaveSuccessful) {
127:        mFinished = true;
128:        mIsSaveSuccessful = isSaveSuccessful;
129:        if (mListener != null) {
130:            mListener.onChosenLockSaveFinished(isSaveSuccessful);
131:        }
132:    }
133:
134:    /**
135:     * Executes the save and verify work in background.
136:     */
137:    @WorkerThread
138:    void saveLock() {
139:        final int userId = getUserId();
140:
141:        // If called after setLockCredential, this will always be true
142:        boolean isPatternEverChosen = getUtils().isPatternEverChosen(userId);
143:
144:        getUtils().setLockCredential(mEnteredCredential, mCurrentCredential, userId);
145:
146:        if (mEnteredCredential.isPattern() && !isPatternEverChosen) {
147:            getUtils().setVisiblePatternEnabled(true, userId);
148:        }
149:    }
150:
151:    // Save chosen lock task.
152:    private class Task extends AsyncTask<Void, Void, Boolean> {
153:        @Override
154:        protected Boolean doInBackground(Void... params) {
155:            return saveAndVerifyInBackground();
156:        }
157:
158:        @Override
159:        protected void onPostExecute(Boolean isSaveSuccessful) {
160:            finish(isSaveSuccessful);
161:        }
162:    }
163:}
