44:
45:    private static final Logger LOG = new Logger(ClearDefaultsPreferenceController.class);
46:
47:    private final IUsbManager mUsbManager;
48:
49:    public ClearDefaultsPreferenceController(Context context, String preferenceKey,
50:            FragmentController fragmentController, CarUxRestrictions uxRestrictions) {
51:        super(context, preferenceKey, fragmentController, uxRestrictions);
52:        IBinder b = ServiceManager.getService(Context.USB_SERVICE);
53:        mUsbManager = IUsbManager.Stub.asInterface(b);
54:    }
55:
56:    @VisibleForTesting
57:    ClearDefaultsPreferenceController(Context context, String preferenceKey,
58:            FragmentController fragmentController, CarUxRestrictions uxRestrictions,
59:            PackageManager packageManager, IUsbManager iUsbManager) {
60:        super(context, preferenceKey, fragmentController, uxRestrictions, packageManager);
61:        mUsbManager = iUsbManager;
62:    }
63:
64:    @Override
65:    protected Class<Preference> getPreferenceType() {
66:        return Preference.class;
67:    }
68:
69:    @Override
70:    protected void updateState(Preference preference) {
71:        boolean autoLaunchEnabled = AppUtils.hasPreferredActivities(mPm, getPackageName())
72:                || isDefaultBrowser(getPackageName())
73:                || hasUsbDefaults(mUsbManager, getPackageName());
74:
75:        preference.setEnabled(autoLaunchEnabled);
76:        if (autoLaunchEnabled) {
77:            preference.setTitle(R.string.auto_launch_reset_text);
78:            preference.setSummary(R.string.auto_launch_enable_text);
79:        } else {
80:            preference.setTitle(R.string.auto_launch_disable_text);
81:            preference.setSummary(null);
82:        }
83:    }
84:
85:    @Override
86:    protected boolean handlePreferenceClicked(Preference preference) {
87:        if (mUsbManager != null) {
88:            int userId = getCurrentUserId();
89:            mPm.clearPackagePreferredActivities(getPackageName());
90:            if (isDefaultBrowser(getPackageName())) {
91:                mPm.setDefaultBrowserPackageNameAsUser(/* packageName= */ null, userId);
92:            }
93:            try {
94:                mUsbManager.clearDefaults(getPackageName(), userId);
95:            } catch (RemoteException e) {
96:                LOG.e("mUsbManager.clearDefaults", e);
97:            }
98:            refreshUi();
99:        }
100:        return true;
101:    }
102:
103:    private boolean isDefaultBrowser(String packageName) {
104:        String defaultBrowser = mPm.getDefaultBrowserPackageNameAsUser(getCurrentUserId());
105:        return packageName.equals(defaultBrowser);
106:    }
107:
108:    private boolean hasUsbDefaults(IUsbManager usbManager, String packageName) {
109:        try {
110:            if (usbManager != null) {
111:                return usbManager.hasDefaults(packageName, getCurrentUserId());
112:            }
113:        } catch (RemoteException e) {
114:            LOG.e("mUsbManager.hasDefaults", e);
115:        }
116:        return false;
117:    }
118:}

