44:/**
45: * Presents the user with information about resetting app preferences.
46: */
47:public class ResetAppPrefFragment extends SettingsFragment {
48:
49:    private static final Logger LOG = new Logger(ResetAppPrefFragment.class);
50:
51:    @Override
52:    @XmlRes
53:    protected int getPreferenceScreenResId() {
54:        return R.xml.reset_app_pref_fragment;
55:    }
56:
57:    @Override
58:    @LayoutRes
59:    protected int getActionBarLayoutId() {
60:        return R.layout.action_bar_with_button;
61:    }
62:
63:    @Override
64:    public void onActivityCreated(Bundle savedInstanceState) {
65:        super.onActivityCreated(savedInstanceState);
66:        Button resetAppsButton = requireActivity().findViewById(R.id.action_button1);
67:        resetAppsButton.setText(requireContext().getString(R.string.reset_app_pref_button_text));
68:        resetAppsButton.setOnClickListener(v -> resetAppPreferences());
69:    }
70:
71:    private void resetAppPreferences() {
72:        new ResetTask(requireContext().getApplicationContext()).execute();
73:    }
74:
75:    private static class ResetTask extends AsyncTask<Void, Void, Void> {
76:
77:        private final WeakReference<Context> mContext;
78:
79:        ResetTask(Context context) {
80:            mContext = new WeakReference<>(context);
81:        }
82:
83:        @Override
84:        protected Void doInBackground(Void... unused) {
85:            Context context = mContext.get();
86:            if (context == null) {
87:                LOG.w("Unable to reset app preferences. Null context");
88:                return null;
89:            }
90:            PackageManager packageManager = context.getPackageManager();
91:            IBinder notificationManagerServiceBinder = ServiceManager.getService(
92:                    Context.NOTIFICATION_SERVICE);
93:            if (notificationManagerServiceBinder == null) {
94:                LOG.w("Unable to reset app preferences. Null notification manager service");
95:                return null;
96:            }
97:            INotificationManager notificationManagerService =
98:                    INotificationManager.Stub.asInterface(notificationManagerServiceBinder);
99:
100:            // Reset app notifications.
101:            // Reset disabled apps.
102:            List<ApplicationInfo> apps = packageManager.getInstalledApplications(
103:                    PackageManager.MATCH_DISABLED_COMPONENTS);
104:            for (ApplicationInfo app : apps) {
105:                try {
106:                    notificationManagerService.setNotificationsEnabledForPackage(
107:                            app.packageName,
108:                            app.uid, true);
109:                } catch (RemoteException e) {
110:                    LOG.w("Unable to reset notification preferences for app: " + app.name, e);
111:                }
112:                if (!app.enabled) {
113:                    if (packageManager.getApplicationEnabledSetting(app.packageName)
114:                            == PackageManager.COMPONENT_ENABLED_STATE_DISABLED_USER) {
115:                        packageManager.setApplicationEnabledSetting(app.packageName,
116:                                PackageManager.COMPONENT_ENABLED_STATE_DEFAULT,
117:                                PackageManager.DONT_KILL_APP);
118:                    }
119:                }
120:            }
121:
122:            // Reset default applications for actions.
123:            // Reset background data restrictions for apps.
124:            // Reset permission restrictions.
125:            try {
126:                IBinder packageManagerServiceBinder = ServiceManager.getService("package");
127:                if (packageManagerServiceBinder == null) {
128:                    LOG.w("Unable to reset app preferences. Null package manager service");
129:                    return null;
130:                }
131:                IPackageManager.Stub.asInterface(
132:                        packageManagerServiceBinder).resetApplicationPreferences(
133:                        new CarUserManagerHelper(context).getCurrentForegroundUserId());
134:            } catch (RemoteException e) {
135:                LOG.w("Unable to reset app preferences", e);
136:            }
137:
138:            // Cleanup.
139:            ((AppOpsManager) context.getSystemService(Context.APP_OPS_SERVICE)).resetAllModes();
140:
141:            return null;
142:        }
143:
144:        @Override
145:        protected void onPostExecute(Void unused) {
146:            super.onPostExecute(unused);
147:            Context context = mContext.get();
148:            if (context != null) {
149:                Toast.makeText(context, R.string.reset_app_pref_complete_toast,
150:                        Toast.LENGTH_SHORT).show();
151:            }
152:        }
153:    }
154:}
