40:/**
41: * Displays the list of apps which have a known premium SMS access state. When a user selects an
42: * app, they are shown a dialog which allows them to configure the state to one of:
43: *
44: * <ul>
45: * <li>Ask - the user will be prompted before app sends premium SMS.
46: * <li>Never allow - app can never send premium SMS.
47: * <li>Always allow - app can automatically send premium SMS.
48: * </ul>
49: */
50:public class PremiumSmsAccessPreferenceController extends PreferenceController<PreferenceGroup> {
51:
52:    private static final Logger LOG = new Logger(PremiumSmsAccessPreferenceController.class);
53:
54:    private static final AppFilter FILTER_SMS_STATE_KNOWN = new AppFilter() {
55:        @Override
56:        public void init() {
57:            // No op.
58:        }
59:
60:        @Override
61:        public boolean filterApp(AppEntry info) {
62:            return info.extraInfo != null
63:                    && (Integer) info.extraInfo != SmsUsageMonitor.PREMIUM_SMS_PERMISSION_UNKNOWN;
64:        }
65:    };
66:
67:    private final ISms mSmsManager;
68:
69:    private final Preference.OnPreferenceChangeListener mOnPreferenceChangeListener =
70:            new Preference.OnPreferenceChangeListener() {
71:                @Override
72:                public boolean onPreferenceChange(Preference preference, Object newValue) {
73:                    PremiumSmsPreference appPreference = (PremiumSmsPreference) preference;
74:                    AppEntry entry = appPreference.mEntry;
75:                    int smsState = Integer.parseInt((String) newValue);
76:                    if (smsState != (Integer) entry.extraInfo) {
77:                        try {
78:                            mSmsManager.setPremiumSmsPermission(entry.info.packageName, smsState);
79:                        } catch (RemoteException e) {
80:                            LOG.w("Unable to set premium sms permission for "
81:                                    + entry.info.packageName + " " + entry.info.uid, e);
82:                            return false;
83:                        }
84:                        // Update the extra info of this entry so that it reflects the new state.
85:                        mAppEntryListManager.forceUpdate(entry);
86:                        return true;
87:                    }
88:                    return false;
89:                }
90:            };
91:
92:    private final AppEntryListManager.Callback mCallback = new AppEntryListManager.Callback() {
93:        @Override
94:        public void onAppEntryListChanged(List<AppEntry> entries) {
95:            mEntries = entries;
96:            refreshUi();
97:        }
98:    };
99:
100:    @VisibleForTesting
101:    AppEntryListManager mAppEntryListManager;
102:    private List<AppEntry> mEntries;
103:
104:    public PremiumSmsAccessPreferenceController(Context context, String preferenceKey,
105:            FragmentController fragmentController, CarUxRestrictions uxRestrictions) {
106:        super(context, preferenceKey, fragmentController, uxRestrictions);
107:        mSmsManager = ISms.Stub.asInterface(ServiceManager.getService("isms"));
108:        mAppEntryListManager = new AppEntryListManager(context);
109:    }
110:
111:    @Override
112:    protected Class<PreferenceGroup> getPreferenceType() {
113:        return PreferenceGroup.class;
114:    }
115:
116:    @Override
117:    protected void onCreateInternal() {
118:        mAppEntryListManager.init(new AppStatePremiumSmsBridge(mSmsManager),
119:                () -> FILTER_SMS_STATE_KNOWN, mCallback);
120:    }
121:
122:    @Override
123:    protected void onStartInternal() {
124:        mAppEntryListManager.start();
125:    }
126:
127:    @Override
128:    protected void onStopInternal() {
129:        mAppEntryListManager.stop();
130:    }
131:
132:    @Override
133:    protected void onDestroyInternal() {
134:        mAppEntryListManager.destroy();
135:    }
136:
137:    @Override
138:    protected void updateState(PreferenceGroup preference) {
139:        if (mEntries == null) {
140:            // Still loading.
141:            return;
142:        }
143:        preference.removeAll();
144:        for (AppEntry entry : mEntries) {
145:            Preference appPreference = new PremiumSmsPreference(getContext(), entry);
146:            appPreference.setOnPreferenceChangeListener(mOnPreferenceChangeListener);
147:            preference.addPreference(appPreference);
148:        }
149:    }
150:
151:    private static class PremiumSmsPreference extends ListPreference {
152:
153:        private final AppEntry mEntry;
154:
155:        PremiumSmsPreference(Context context, AppEntry entry) {
156:            super(context);
157:            String key = entry.info.packageName + "|" + entry.info.uid;
158:            setKey(key);
159:            setTitle(entry.label);
160:            setIcon(entry.icon);
161:            setPersistent(false);
162:            setEntries(R.array.premium_sms_access_values);
163:            setEntryValues(new CharSequence[]{
164:                    String.valueOf(SmsUsageMonitor.PREMIUM_SMS_PERMISSION_ASK_USER),
165:                    String.valueOf(SmsUsageMonitor.PREMIUM_SMS_PERMISSION_NEVER_ALLOW),
166:                    String.valueOf(SmsUsageMonitor.PREMIUM_SMS_PERMISSION_ALWAYS_ALLOW)
167:            });
168:            setValue(String.valueOf(entry.extraInfo));
169:            setSummary("%s");
170:            mEntry = entry;
171:        }
172:    }
