50:/** Unit test for {@link AppsNetworkStatsManager}. */
51:@RunWith(CarSettingsRobolectricTestRunner.class)
52:@Config(shadows = {ShadowINetworkStatsServiceStub.class, ShadowNetworkPolicyManager.class})
53:public class AppsNetworkStatsManagerTest {
54:
55:    private Context mContext;
56:    private AppsNetworkStatsManager mAppsNetworkStatsManager;
57:
58:    @Captor
59:    private ArgumentCaptor<LoaderManager.LoaderCallbacks<NetworkStats>>
60:            mCallbacksArgumentCaptor;
61:
62:    @Mock
63:    private AppsNetworkStatsManager.Callback mCallback1;
64:
65:    @Mock
66:    private AppsNetworkStatsManager.Callback mCallback2;
67:
68:    @Mock
69:    private LoaderManager mLoaderManager;
70:
71:    @Mock
72:    private INetworkStatsService mINetworkStatsService;
73:
74:    @Mock
75:    private INetworkStatsSession mINetworkStatsSession;
76:
77:    @Mock
78:    private NetworkPolicyManager mNetworkPolicyManager;
79:
80:    @Before
81:    public void setUp() throws Exception {
82:        MockitoAnnotations.initMocks(this);
83:        mContext = RuntimeEnvironment.application;
84:
85:        when(mINetworkStatsService.openSession()).thenReturn(mINetworkStatsSession);
86:        ShadowINetworkStatsServiceStub.setINetworkStatsSession(mINetworkStatsService);
87:
88:        when(mNetworkPolicyManager.getUidsWithPolicy(anyInt())).thenReturn(new int[0]);
89:        ShadowNetworkPolicyManager.setNetworkPolicyManager(mNetworkPolicyManager);
90:
91:        mAppsNetworkStatsManager = new AppsNetworkStatsManager(mContext);
92:        mAppsNetworkStatsManager.startLoading(mLoaderManager, Bundle.EMPTY);
93:
94:        verify(mLoaderManager).restartLoader(eq(1), eq(Bundle.EMPTY),
95:                mCallbacksArgumentCaptor.capture());
96:    }
97:
98:    @After
99:    public void tearDown() {
100:        ShadowINetworkStatsServiceStub.reset();
101:        ShadowNetworkPolicyManager.reset();
102:    }
103:
104:    @Test
105:    public void callback_onLoadFinished_listenerOnDataLoadedCalled() throws Exception {
106:        mAppsNetworkStatsManager.registerListener(mCallback1);
107:        mAppsNetworkStatsManager.registerListener(mCallback2);
108:
109:        NetworkStats networkStats = new NetworkStats(0, 0);
110:
111:        mCallbacksArgumentCaptor.getValue().onLoadFinished(null, networkStats);
112:
113:        verify(mCallback1).onDataLoaded(eq(networkStats), any());
114:        verify(mCallback2).onDataLoaded(eq(networkStats), any());
115:    }
116:
117:    @Test
118:    public void callback_unregisterListener_onlyOneListenerOnDataLoadedCalled() throws Exception {
119:        mAppsNetworkStatsManager.registerListener(mCallback1);
120:        mAppsNetworkStatsManager.registerListener(mCallback2);
121:        mAppsNetworkStatsManager.unregisterListener(mCallback2);
122:
123:        NetworkStats networkStats = new NetworkStats(0, 0);
124:
125:        mCallbacksArgumentCaptor.getValue().onLoadFinished(null, networkStats);
126:
127:        verify(mCallback1).onDataLoaded(eq(networkStats), any());
128:        verify(mCallback2, never()).onDataLoaded(eq(networkStats), any());
129:    }
130:
131:    @Test
132:    public void callback_notLoaded_listenerOnDataLoadedNotCalled() throws Exception {
133:        mAppsNetworkStatsManager.registerListener(mCallback1);
134:        mAppsNetworkStatsManager.registerListener(mCallback2);
135:        mAppsNetworkStatsManager.unregisterListener(mCallback2);
136:
137:        NetworkStats networkStats = new NetworkStats(0, 0);
138:
139:        verify(mCallback1, never()).onDataLoaded(eq(networkStats), any());
140:        verify(mCallback2, never()).onDataLoaded(eq(networkStats), any());
141:    }
